// 原实际completion编解码往返与外层冲突拒绝；不以该局部来源形状代完整Birth/relief验收。
#include "resident/domains/family/family_care_completion_shape.hpp"
#include "resident/checkpoint/completion_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool yes,const char* text){++checks;if(!yes)throw std::runtime_error(text);}}
int main(){try{for(const auto& reason:std::vector<StableId>{"","CaregiverDied","CareReliefProviderStopped"}){const bool success=reason.empty();ActionCompletion hot;hot.completed=true;hot.success=success;if(!reason.empty())hot.code=reason;FamilyEffect effect;effect.success=success;effect.actor_id="caregiver";effect.player_actor_id="player";effect.fact_id="family_birth:8";if(!reason.empty())effect.code=reason;hot.family=effect;auto valid=[&](const ActionCompletion& c){return validate_family_care_completion_shape(c,"caregiver","player","family_birth:8",success,reason).ok;};check(valid(hot),"exact hot family completion");auto json=encode_action_completion(hot);check(json.ok,"original codec encodes family completion");auto cold=decode_action_completion(json.value);check(cold.ok&&!cold.value->completed&&!cold.value->success&&!cold.value->code&&valid(*cold.value),"original JSON flattened FamilyEffect keeps same verified outcome");auto bad=hot;bad.success=!success;check(!valid(bad),"present outer success cannot disagree with original source");bad=hot;bad.code="WrongReason";check(!valid(bad),"present outer reason cannot disagree");bad=hot;bad.completed=false;check(!valid(bad),"present nonterminal flag cannot describe terminal care");bad=hot;bad.growth=GrowthEffect{};check(!valid(bad),"mixed growth and family completion rejected");bad=*cold.value;bad.family->fact_id="family_birth:9";check(!valid(bad),"cold effect cannot borrow another source");}std::cout<<"FAMILY_CARE_COMPLETION_SHAPE "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
